import AppKit
import XCTest
@testable import ThumbFreeApp

/// The Mac's own: what `MacEnvironment` puts on the pasteboard.
final class MacEnvironmentTests: XCTestCase {
    private static let markers: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.AutoGeneratedType", "org.nspasteboard.TransientType",
    ]

    /// Text ThumbFree puts there when it quits is marked for clipboard managers (nspasteboard.org) as private and not
    /// copied by you, but not as transient: it's there to be pasted. Text you copy has no marks.
    func testConcealedTextIsMarkedForClipboardManagersButCopiedTextIsnt() throws {
        let named = NSPasteboard.withUniqueName()
        defer { named.releaseGlobally() }
        let environment = MacEnvironment(pasteboard: named)

        environment.copyText("Private words.", concealed: true)

        XCTAssertEqual(named.string(forType: .string), "Private words.")
        let concealed = Set(try XCTUnwrap(named.pasteboardItems?.first).types.map(\.rawValue))
        XCTAssertEqual(
            concealed.intersection(Self.markers),
            ["org.nspasteboard.ConcealedType", "org.nspasteboard.AutoGeneratedType"])

        environment.copyText("Copied words.")

        XCTAssertEqual(named.string(forType: .string), "Copied words.")
        let copied = Set(try XCTUnwrap(named.pasteboardItems?.first).types.map(\.rawValue))
        XCTAssertTrue(copied.isDisjoint(with: Self.markers), "\(copied)")
    }
}
